def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    bg = max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    def nbrs(r,c):
        return [(rr,cc) for rr in range(H) for cc in range(W)
                if (rr,cc)!=(r,c) and abs(rr-r)<=1 and abs(cc-c)<=1 and g[rr][cc]!=bg]
    deg={p:len(nbrs(*p)) for p in cells}
    for p in cells:
        if deg[p]==1:
            n=nbrs(*p)[0]
            dr,dc=p[0]-n[0],p[1]-n[1]
            r,c=p[0]+dr,p[1]+dc
            while 0<=r<H and 0<=c<W:
                g[r][c]=g[p[0]][p[1]]; r+=dr; c+=dc
    return g

